const config = {
  schemaVersion: 1,
  locations: {
    mode: 'all_uae', // 'all_uae' or 'selected'
    emirates: ['Abu Dhabi', 'Dubai', 'Sharjah', 'Ajman', 'Umm Al Quwain', 'Ras Al Khaimah', 'Fujairah'],
    allowUnspecifiedUae: true,
  },
  roles: {
    include: ['operations', 'coordinator', 'administration', 'project management', 'business support'],
    exclude: ['commission only', 'door to door'],
  },
  workModes: ['on-site', 'hybrid', 'remote'],
  employmentTypes: ['full-time', 'part-time', 'contract', 'internship'],
  uaeNationalRoles: {
    mode: 'include', // 'include', 'only', 'exclude', or 'ignore'
    keywords: ['UAE National', 'Emirati', 'Emiratisation', 'Emiratization'],
  },
  preferredCompanies: [],
  salary: { minimumAed: 0, rewardWhenMentioned: true },
  scoring: {
    role: 35,
    location: 25,
    workMode: 10,
    uaeNational: 15,
    preferredCompany: 10,
    salaryMentioned: 5,
    excludedKeywordPenalty: 60,
    notifyAt: 70,
    trackAt: 45,
  },
  duplicateWindowDays: 30,
  telegram: {
    enabled: true,
    chatId: 'REPLACE_WITH_YOUR_CHAT_ID',
    disableWebPagePreview: true,
  },
  tracking: {
    mode: 'none', // 'none', 'google_sheets', or 'csv'
    googleSheetId: 'REPLACE_WITH_YOUR_SHEET_ID',
    sheetName: 'Jobs',
  },
};

const validModes = ['include', 'only', 'exclude', 'ignore'];
if (!validModes.includes(config.uaeNationalRoles.mode)) throw new Error('Invalid UAE National mode');
if (!['all_uae', 'selected'].includes(config.locations.mode)) throw new Error('Invalid location mode');
if (config.scoring.notifyAt < config.scoring.trackAt) throw new Error('notifyAt must be greater than or equal to trackAt');
if (config.scoring.notifyAt > 100 || config.scoring.trackAt < 0) throw new Error('Score thresholds must be between 0 and 100');

return $input.all().map(item => ({ json: { ...item.json, _config: config }, binary: item.binary }));

const aliases = {
  'Abu Dhabi': ['abu dhabi', 'al ain', 'western region'],
  Dubai: ['dubai', 'jebel ali'],
  Sharjah: ['sharjah', 'khor fakkan', 'kalba'],
  Ajman: ['ajman'],
  'Umm Al Quwain': ['umm al quwain', 'umm al-quwain', 'uaq'],
  'Ras Al Khaimah': ['ras al khaimah', 'ras al-khaimah', 'rak'],
  Fujairah: ['fujairah'],
};

const cleanHtml = value => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&#39;/gi, "'")
  .replace(/&quot;/gi, '"')
  .replace(/\s+/g, ' ')
  .trim();
const asText = value => typeof value === 'string' ? value : JSON.stringify(value || '');
const includesAny = (text, values) => values.filter(value => text.includes(String(value).toLowerCase()));
const firstMeaningfulLine = lines => lines.find(line => line.length > 2 && !/^view job|^apply|^http/i.test(line)) || '';

return $input.all().map(item => {
  const input = item.json;
  const config = input._config;
  const subject = asText(input.subject).trim();
  const plain = asText(input.textPlain || input.text || input.textAsHtml);
  const htmlText = cleanHtml(input.html || input.htmlBody);
  const rawText = [subject, plain, htmlText].filter(Boolean).join('\n');
  const normalizedText = rawText.toLowerCase().replace(/\s+/g, ' ').trim();
  const lines = plain.split(/\r?\n/).map(line => line.trim()).filter(Boolean);

  const urlMatches = rawText.match(/https?:\/\/[^\s<>"']+/gi) || [];
  const applicationUrl = (urlMatches.find(url => /job|career|vacan|position|apply/i.test(url)) || urlMatches[0] || '')
    .replace(/[),.;]+$/, '');

  const fromValue = input.from || input.sender || '';
  const fromText = typeof fromValue === 'string' ? fromValue : (fromValue.text || fromValue.value?.[0]?.name || fromValue.value?.[0]?.address || '');
  const sourceRules = [
    ['LinkedIn', /linkedin/i], ['Indeed', /indeed/i], ['Bayt', /bayt/i],
    ['GulfTalent', /gulftalent/i], ['Naukrigulf', /naukri.?gulf/i], ['Glassdoor', /glassdoor/i],
  ];
  const source = sourceRules.find(([, rule]) => rule.test(fromText + ' ' + normalizedText))?.[0] || (fromText.match(/^([^<]+)/)?.[1]?.trim() || 'Email alert');

  let title = subject
    .replace(/^(new |recommended |daily |weekly )?(job )?(match|alert|opportunity|vacancy)[: –-]*/i, '')
    .replace(/\s+(in|at)\s+(abu dhabi|dubai|sharjah|ajman|umm al quwain|ras al khaimah|fujairah).*$/i, '')
    .trim();
  if (!title || title.length > 140) title = firstMeaningfulLine(lines) || 'Untitled role';
  const titleIndex = lines.findIndex(line => line.toLowerCase() === title.toLowerCase());
  const companyCandidate = titleIndex >= 0 ? lines[titleIndex + 1] : lines[1];
  const company = companyCandidate && companyCandidate.length < 120 && !/uae|emirates|remote|hybrid|full-time|part-time|contract/i.test(companyCandidate)
    ? companyCandidate
    : (fromText.match(/^([^<]+)/)?.[1]?.trim() || 'Unknown company');

  const detectedLocations = Object.entries(aliases)
    .filter(([, values]) => values.some(value => normalizedText.includes(value)))
    .map(([emirate]) => emirate);
  const mentionsUae = /\buae\b|united arab emirates/i.test(rawText);
  const allowedLocations = config.locations.mode === 'all_uae' ? Object.keys(aliases) : config.locations.emirates;
  const locationMatch = detectedLocations.some(location => allowedLocations.includes(location)) ||
    (detectedLocations.length === 0 && mentionsUae && config.locations.allowUnspecifiedUae);

  const workMode = /\bhybrid\b/i.test(rawText) ? 'hybrid' : /\bremote\b|work from home/i.test(rawText) ? 'remote' : /on[ -]?site|office[ -]?based/i.test(rawText) ? 'on-site' : 'unspecified';
  const employmentType = /part[ -]?time/i.test(rawText) ? 'part-time' : /full[ -]?time|permanent/i.test(rawText) ? 'full-time' : /intern(ship)?/i.test(rawText) ? 'internship' : /contract|temporary|freelance/i.test(rawText) ? 'contract' : 'unspecified';
  const uaeNationalRole = includesAny(normalizedText, config.uaeNationalRoles.keywords.map(value => value.toLowerCase())).length > 0;
  const matchedRoleKeywords = includesAny(normalizedText, config.roles.include.map(value => value.toLowerCase()));
  const excludedKeywords = includesAny(normalizedText, config.roles.exclude.map(value => value.toLowerCase()));
  const preferredCompany = config.preferredCompanies.some(value => company.toLowerCase().includes(String(value).toLowerCase()));
  const salaryMatch = rawText.match(/(?:AED|د\.?إ)\s*[\d,]+(?:\s*[-–to]+\s*(?:AED|د\.?إ)?\s*[\d,]+)?(?:\s*(?:per|\/)\s*(?:month|year|annum))?/i);

  const matchedSignals = [];
  let score = 0;
  if (matchedRoleKeywords.length) { score += config.scoring.role; matchedSignals.push('role'); }
  if (locationMatch) { score += config.scoring.location; matchedSignals.push('location'); }
  if (workMode !== 'unspecified' && config.workModes.includes(workMode)) { score += config.scoring.workMode; matchedSignals.push('work mode'); }
  if (uaeNationalRole && ['include', 'only'].includes(config.uaeNationalRoles.mode)) { score += config.scoring.uaeNational; matchedSignals.push('UAE National'); }
  if (preferredCompany) { score += config.scoring.preferredCompany; matchedSignals.push('preferred company'); }
  if (salaryMatch && config.salary.rewardWhenMentioned) { score += config.scoring.salaryMentioned; matchedSignals.push('salary mentioned'); }
  if (excludedKeywords.length) { score -= config.scoring.excludedKeywordPenalty; matchedSignals.push('excluded keyword penalty'); }

  const workModeEligible = workMode === 'unspecified' || config.workModes.includes(workMode);
  const employmentEligible = employmentType === 'unspecified' || config.employmentTypes.includes(employmentType);
  const nationalEligible = config.uaeNationalRoles.mode === 'ignore' || config.uaeNationalRoles.mode === 'include' ||
    (config.uaeNationalRoles.mode === 'only' && uaeNationalRole) ||
    (config.uaeNationalRoles.mode === 'exclude' && !uaeNationalRole);
  const eligible = locationMatch && workModeEligible && employmentEligible && nationalEligible && excludedKeywords.length === 0;
  if (!eligible) score = Math.min(score, config.scoring.trackAt - 1);
  score = Math.max(0, Math.min(100, Math.round(score)));

  return { json: {
    _config: config, subject, source, title, company,
    location: detectedLocations.join(', ') || (mentionsUae ? 'UAE (emirate unspecified)' : 'Unspecified'),
    detectedLocations, workMode, employmentType, uaeNationalRole,
    salaryText: salaryMatch?.[0] || '', applicationUrl,
    matchedRoleKeywords, excludedKeywords, matchedSignals, eligible, score,
    receivedAt: input.date || input.receivedDate || new Date().toISOString(),
    normalizedText: normalizedText.slice(0, 12000),
  }, binary: item.binary };
});

const store = $getWorkflowStaticData('global');
store.seenJobs = store.seenJobs || {};
const now = Date.now();

const hash = value => {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
};

const output = [];
for (const item of $input.all()) {
  const retentionMs = Math.max(1, Number(item.json._config.duplicateWindowDays || 30)) * 86400000;
  for (const [key, timestamp] of Object.entries(store.seenJobs)) {
    if (now - Number(timestamp) > retentionMs) delete store.seenJobs[key];
  }
  const identity = (item.json.applicationUrl || [item.json.company, item.json.title, item.json.location].join('|')).toLowerCase().trim();
  const dedupeKey = hash(identity);
  if (store.seenJobs[dedupeKey]) continue;
  store.seenJobs[dedupeKey] = now;
  output.push({ json: { ...item.json, dedupeKey, duplicate: false }, binary: item.binary });
}
return output;

return $input.all().map(item => {
  const j = item.json;
  const lines = [
    `🇦🇪 UAE JOB MATCH · ${j.score}/100`, '',
    j.title, j.company, '',
    `📍 ${j.location}`,
    `🏢 ${j.workMode} · ${j.employmentType}`,
    `⭐ Matched: ${j.matchedSignals.join(', ') || 'general criteria'}`, '',
    `Source: ${j.source}`,
  ];
  if (j.salaryText) lines.push(`Salary text: ${j.salaryText}`);
  if (j.applicationUrl) lines.push(`Open job: ${j.applicationUrl}`);
  lines.push('', 'Verify the vacancy and employer before applying.');
  return { json: { ...j, telegramText: lines.join('\n') }, binary: item.binary };
});

return $input.all().map(item => {
  const j = item.json;
  return { json: {
    dedupe_key: j.dedupeKey,
    date_found: new Date(j.receivedAt).toISOString(),
    company: j.company,
    job_title: j.title,
    location: j.location,
    work_mode: j.workMode,
    employment_type: j.employmentType,
    source: j.source,
    match_score: j.score,
    uae_national_role: j.uaeNationalRole,
    application_url: j.applicationUrl,
    status: 'New',
    date_applied: '',
    interview_date: '',
    notes: j.matchedSignals.join(', '),
  } };
});
